  const expectedCopy={synthetic:true,contextId:ctx.contextId,module:root.module,exclusiveDestination:true,noLinks:true};const copied=await effect(label+'.verify.copy',structuredClone(expectedCopy));await validate(label+'.verify.copy.validation',()=>assert.deepEqual(copied,expectedCopy));
